// Reef tank pH logger.
// Linearized probe on A0, optional low-pH LED on D13, UART log at 9600.

const int PROBE_PIN = A0;
const int ALERT_PIN = 13;
const float ALERT_PH = 7.20f;
const float ALERT_PH_CLEAR = 7.30f;
const unsigned long LOG_PERIOD_MS = 1000;

unsigned long lastLogMs = 0;
unsigned long sampleCount = 0;
float lastPh = 0.0f;
float phMin = 14.0f;
float phMax = 0.0f;
bool alertOn = false;

float adcToMillivolts(int raw)
{
    return raw * (5000.0f / 1023.0f);
}

float computePh(float millivolts)
{
    return millivolts / 500.0f;
}

void trackRange(float ph)
{
    if (ph < phMin)
    {
        phMin = ph;
    }
    if (ph > phMax)
    {
        phMax = ph;
    }
}

void setAlert(bool on)
{
    alertOn = on;
    digitalWrite(ALERT_PIN, on ? HIGH : LOW);
}

void writeLogLine()
{
    Serial.print("pH: ");
    Serial.println(lastPh, 2);
}

void setup()
{
    pinMode(ALERT_PIN, OUTPUT);
    digitalWrite(ALERT_PIN, LOW);
    Serial.begin(9600);
    lastLogMs = millis();
}

void loop()
{
    int raw = analogRead(PROBE_PIN);
    float mv = adcToMillivolts(raw);
    lastPh = computePh(mv);
    sampleCount++;
    trackRange(lastPh);

    if (lastPh < ALERT_PH)
    {
        setAlert(true);
    }
    else if (lastPh >= ALERT_PH_CLEAR)
    {
        setAlert(false);
    }

    unsigned long now = millis();
    if (now - lastLogMs >= LOG_PERIOD_MS)
    {
        lastLogMs = now;
        writeLogLine();
    }
}

// Attic ridge-vent controller for an Uno.
// LM35 on A0, relay driver on D8, momentary override on D3 (pull-up).

const int TEMP_PIN = A0;
const int FAN_PIN = 8;
const int OVERRIDE_PIN = 3;

const float FAN_ON_C = 42.0f;
const float FAN_OFF_C = 38.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long OVERRIDE_DEBOUNCE_MS = 30;
const unsigned long TEMP_CONFIRM_MS = 300;

bool fanRunning = false;
unsigned long lastSampleMs = 0;
unsigned long lastStatusMs = 0;
float lastTempC = 0.0f;

bool overrideStable = false;
bool overrideLastRaw = false;
unsigned long overrideChangeMs = 0;

bool tempWantOn = false;
bool tempCandidateOn = false;
unsigned long tempCandidateMs = 0;

float readAtticTempC()
{
    int raw = analogRead(TEMP_PIN);
    float millivolts = raw * (5000.0f / 1023.0f);
    return millivolts / MV_PER_C;
}

void applyFan(bool wantOn)
{
    fanRunning = wantOn;
    digitalWrite(FAN_PIN, wantOn ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("attic: ");
    Serial.print(lastTempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanRunning ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(OVERRIDE_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSampleMs = millis();
    lastStatusMs = millis();
    overrideLastRaw = (digitalRead(OVERRIDE_PIN) == LOW);
    overrideStable = overrideLastRaw;
    overrideChangeMs = millis();
    tempWantOn = false;
    tempCandidateOn = false;
    tempCandidateMs = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSampleMs >= SAMPLE_MS)
    {
        lastSampleMs = now;
        lastTempC = readAtticTempC();

        // Debounce the override button: require the raw reading to hold.
        bool overrideRaw = (digitalRead(OVERRIDE_PIN) == LOW);
        if (overrideRaw != overrideLastRaw)
        {
            overrideLastRaw = overrideRaw;
            overrideChangeMs = now;
        }
        if (now - overrideChangeMs >= OVERRIDE_DEBOUNCE_MS)
        {
            overrideStable = overrideRaw;
        }

        // Hysteresis: ON at >= 42 C, OFF at <= 38 C.
        bool wantOn = tempWantOn;
        if (lastTempC >= FAN_ON_C)
        {
            wantOn = true;
        }
        else if (lastTempC <= FAN_OFF_C)
        {
            wantOn = false;
        }

        // Confirm the temperature decision holds continuously before acting.
        if (wantOn != tempCandidateOn)
        {
            tempCandidateOn = wantOn;
            tempCandidateMs = now;
        }
        if (now - tempCandidateMs >= TEMP_CONFIRM_MS)
        {
            tempWantOn = tempCandidateOn;
        }

        if (overrideStable)
        {
            applyFan(true);
        }
        else
        {
            applyFan(tempWantOn);
        }
    }

    if (now - lastStatusMs >= STATUS_MS)
    {
        lastStatusMs = now;
        publishStatus();
    }
}

// Electronics-bench user LED mirror.
// Momentary probe button on D2 (pull-up), user LED on D13.
// Mode switch on D4 (pull-up) selects steady vs blink-while-held.

const int BTN_PIN = 2;
const int LED_PIN = 13;
const int MODE_PIN = 4;
const unsigned long BLINK_MS = 120;
const unsigned long STATUS_MS = 1000;

bool lit = false;
bool blinking = false;
unsigned long lastBlink = 0;
unsigned long lastStatus = 0;
unsigned long pressMs = 0;

void setLed(bool on)
{
    lit = on;
    digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("bench led=");
    Serial.print(lit ? 1 : 0);
    Serial.print(" held_ms=");
    Serial.println(pressMs);
}

void setup()
{
    pinMode(BTN_PIN, INPUT_PULLUP);
    pinMode(MODE_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    setLed(false);
    Serial.begin(9600);
    lastBlink = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    bool pressed = (digitalRead(BTN_PIN) == LOW);
    bool blinkMode = (digitalRead(MODE_PIN) == LOW);

    if (!pressed)
    {
        pressMs = 0;
        blinking = false;
        setLed(false);
    }
    else if (!blinkMode)
    {
        pressMs = now;
        blinking = false;
        setLed(true);
    }
    else
    {
        if (!blinking)
        {
            blinking = true;
            pressMs = now;
            lastBlink = now;
            setLed(true);
        }
        if (now - lastBlink >= BLINK_MS)
        {
            lastBlink += BLINK_MS;
            setLed(!lit);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Blend-tank concentration logger for a process skid.
// Probe on A4 (10 mV/%). Sample button on D5 (pull-up) forces an early print.

const int CONC_PIN = A4;
const int SAMPLE_BTN = 5;
const int WINDOW = 8;
const float MV_PER_PCT = 10.0f;
const unsigned long IDLE_MS = 20;
const unsigned long STATUS_MS = 1000;
const unsigned long DEBOUNCE_MS = 30;

int samples[WINDOW];
int sampleIdx = 0;
int sampleCount = 0;
long sampleSum = 0;
float lastPct = 0.0f;
unsigned long lastStatus = 0;
unsigned long batches = 0;
int lastBtn = HIGH;
int btnStable = HIGH;
unsigned long btnChange = 0;

float rawToPct(int raw)
{
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_PCT;
}

void resetWindow()
{
    sampleIdx = 0;
    sampleCount = 0;
    sampleSum = 0;
}

void addSample(int raw)
{
    if (sampleCount < WINDOW)
    {
        samples[sampleIdx] = raw;
        sampleSum += raw;
        sampleCount++;
    }
    else
    {
        sampleSum -= samples[sampleIdx];
        samples[sampleIdx] = raw;
        sampleSum += raw;
    }
    sampleIdx = (sampleIdx + 1) % WINDOW;
}

int windowAverage()
{
    if (sampleCount == 0)
    {
        return 0;
    }
    return (int)(sampleSum / sampleCount);
}

void publishPct(float pct)
{
    Serial.print("pct: ");
    Serial.println(pct, 1);
    lastPct = pct;
    batches++;
}

void forceSampleNote()
{
    Serial.print("blend force last=");
    Serial.println(lastPct, 1);
}

void setup()
{
    pinMode(SAMPLE_BTN, INPUT_PULLUP);
    Serial.begin(9600);
    resetWindow();
    lastStatus = millis();
    lastBtn = digitalRead(SAMPLE_BTN);
    btnStable = lastBtn;
    btnChange = millis();
}

void loop()
{
    int raw = analogRead(CONC_PIN);
    addSample(raw);

    unsigned long now = millis();

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        int avg = windowAverage();
        float pct = rawToPct(avg);
        publishPct(pct);
        Serial.print("blend batches=");
        Serial.println(batches);
    }

    int btn = digitalRead(SAMPLE_BTN);
    if (btn != lastBtn)
    {
        lastBtn = btn;
        btnChange = now;
    }
    if (now - btnChange >= DEBOUNCE_MS && btn != btnStable)
    {
        btnStable = btn;
        if (btnStable == LOW)
        {
            forceSampleNote();
        }
    }

    delay(IDLE_MS);
}

// Small boiler gas-valve thermostat.
// Probe on A1 (10 mV/°C), gas valve on D6, lockout key on D3.

const int TEMP_PIN = A1;
const int VALVE_PIN = 6;
const int LOCK_PIN = 3;
const float FIRE_ON_C = 70.0f;
const float FIRE_OFF_C = 75.0f;
const float FAULT_HIGH_C = 120.0f;
const float FAULT_LOW_C = 5.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 40;
const unsigned long STATUS_MS = 1000;

bool firing = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readBoilerC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setValve(bool openValve)
{
    firing = openValve;
    digitalWrite(VALVE_PIN, openValve ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("boiler: ");
    Serial.print(tempC, 1);
    Serial.print(" C valve=");
    Serial.println(firing ? "OPEN" : "SHUT");
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(LOCK_PIN, INPUT_PULLUP);
    setValve(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readBoilerC();
        bool locked = (digitalRead(LOCK_PIN) == LOW);
        bool fault = (tempC > FAULT_HIGH_C) || (tempC < FAULT_LOW_C);

        if (locked || fault)
        {
            setValve(false);
        }
        else if (tempC < FIRE_ON_C)
        {
            setValve(true);
        }
        else if (tempC > FIRE_OFF_C)
        {
            setValve(false);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Cabin heater enable with comfort band.
// LM35 on A0, heater relay on D9, frost override on D2 (pull-up).

const int TEMP_PIN = A0;
const int HEAT_PIN = 9;
const int FROST_PIN = 2;
const float HEAT_ON_C = 18.0f;
const float HEAT_OFF_C = 22.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long FROST_HOLD_MS = 100;

bool heaterOn = false;
unsigned long lastSample = 0;
unsigned long lastStatus = 0;
unsigned long frostSince = 0;
bool frostActive = false;
float lastC = 0.0f;

float readCabinC()
{
    int mv = analogRead(TEMP_PIN) * 5000 / 1023;
    return mv / MV_PER_C;
}

void applyHeater(bool on)
{
    heaterOn = on;
    digitalWrite(HEAT_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("cabin: ");
    Serial.print(lastC, 1);
    Serial.print(" C heat=");
    Serial.println(heaterOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(HEAT_PIN, OUTPUT);
    pinMode(FROST_PIN, INPUT_PULLUP);
    applyHeater(false);
    Serial.begin(9600);
    lastSample = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        lastC = readCabinC();
        bool frost = (digitalRead(FROST_PIN) == LOW);

        if (frost)
        {
            if (!frostActive)
            {
                frostActive = true;
                frostSince = now;
            }
        }
        else
        {
            frostActive = false;
        }

        if (frostActive && (now - frostSince >= FROST_HOLD_MS))
        {
            applyHeater(true);
        }
        else if (lastC < HEAT_ON_C)
        {
            applyHeater(true);
        }
        else if (lastC > HEAT_OFF_C)
        {
            applyHeater(false);
        }
        else
        {
            applyHeater(false);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Basement sump controller.
// Ultrasonic level proxy as linear voltage on A1, pump contactor on D7,
// silence button on D4 (active LOW, pull-up).

const uint8_t LEVEL_PIN = A1;
const uint8_t PUMP_PIN = 7;
const uint8_t SILENCE_PIN = 4;

const float START_CM = 45.0f;
const float STOP_CM = 30.0f;
const float MV_PER_CM = 10.0f;
const unsigned long POLL_MS = 40;
const unsigned long LOG_MS = 800;
const unsigned long CONFIRM_MS = 300;

bool pumpOn = false;
bool silenceLatched = false;
unsigned long lastPoll = 0;
unsigned long lastLog = 0;
float levelCm = 0.0f;

bool pendingState = false;
bool pendingActive = false;
unsigned long pendingSince = 0;

float sampleLevelCm()
{
    int adc = analogRead(LEVEL_PIN);
    float mv = adc * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void setPump(bool on)
{
    pumpOn = on;
    digitalWrite(PUMP_PIN, on ? HIGH : LOW);
}

void emitLog()
{
    Serial.print("sump cm=");
    Serial.print(levelCm, 1);
    Serial.print(" pump=");
    Serial.print(pumpOn ? 1 : 0);
    Serial.print(" mute=");
    Serial.println(silenceLatched ? 1 : 0);
}

void setup()
{
    pinMode(PUMP_PIN, OUTPUT);
    pinMode(SILENCE_PIN, INPUT_PULLUP);
    digitalWrite(PUMP_PIN, LOW);
    Serial.begin(9600);
    lastPoll = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long t = millis();

    if (digitalRead(SILENCE_PIN) == LOW)
    {
        silenceLatched = true;
        setPump(false);
        pendingActive = false;
    }

    if (t - lastPoll >= POLL_MS)
    {
        lastPoll = t;
        levelCm = sampleLevelCm();

        if (!silenceLatched)
        {
            // Hysteresis: start at or above START_CM, stop at or below STOP_CM.
            bool want = pumpOn;
            if (levelCm >= START_CM)
            {
                want = true;
            }
            else if (levelCm <= STOP_CM)
            {
                want = false;
            }

            if (want != pumpOn)
            {
                // Require the new state to hold continuously before switching.
                if (!pendingActive || pendingState != want)
                {
                    pendingActive = true;
                    pendingState = want;
                    pendingSince = t;
                }
                else if (t - pendingSince >= CONFIRM_MS)
                {
                    setPump(want);
                    pendingActive = false;
                }
            }
            else
            {
                pendingActive = false;
            }
        }
    }

    if (t - lastLog >= LOG_MS)
    {
        lastLog = t;
        emitLog();
    }
}

// Greenhouse nutrient drip pulse scheduler.
// Pulse driver on D8, pause button on D4 (pull-up).

const int DRIP_PIN = 8;
const int PAUSE_PIN = 4;
const byte PERIOD_MS = 800;
const unsigned long PULSE_MS = 50;
const unsigned long LOG_MS = 1600;

unsigned long nextDue = 0;
unsigned long pulseUntil = 0;
unsigned long lastLog = 0;
unsigned long dripCount = 0;
bool pulsing = false;
bool paused = false;

void dripHigh()
{
    digitalWrite(DRIP_PIN, HIGH);
}

void dripLow()
{
    digitalWrite(DRIP_PIN, LOW);
}

void startPulse(unsigned long now)
{
    pulsing = true;
    pulseUntil = now + PULSE_MS;
    dripHigh();
    dripCount++;
    Serial.println("drip");
}

void endPulse()
{
    pulsing = false;
    dripLow();
}

void printLog()
{
    Serial.print("drip n=");
    Serial.print(dripCount);
    Serial.print(" pause=");
    Serial.println(paused ? 1 : 0);
}

void setup()
{
    pinMode(DRIP_PIN, OUTPUT);
    pinMode(PAUSE_PIN, INPUT_PULLUP);
    dripLow();
    Serial.begin(9600);
    nextDue = millis() + PERIOD_MS;
    lastLog = millis();
}

void loop()
{
    unsigned long now = millis();
    paused = (digitalRead(PAUSE_PIN) == LOW);

    if (pulsing && (long)(now - pulseUntil) >= 0)
    {
        endPulse();
    }

    if (!paused && !pulsing && (long)(now - nextDue) >= 0)
    {
        nextDue = now + PERIOD_MS;
        startPulse(now);
    }

    if (paused)
    {
        nextDue = now + PERIOD_MS;
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        printLog();
    }
}

// Foyer wall switch: one pushbutton toggles a lamp channel.
// Button D5 to ground (pull-up), lamp driver D11, status over serial.

const int SWITCH_PIN = 5;
const int LAMP_PIN = 11;
const unsigned long STATUS_EVERY_MS = 1500;
const unsigned long SETTLE_MS = 40;

bool lampLit = false;
int previousRaw = HIGH;
bool pressArmed = true;
unsigned long lowSince = 0;
unsigned long lastStatusAt = 0;
unsigned long pressEvents = 0;
unsigned long bootMs = 0;

void driveLamp(bool on)
{
    lampLit = on;
    digitalWrite(LAMP_PIN, on ? HIGH : LOW);
}

void flipLamp()
{
    driveLamp(!lampLit);
    pressEvents++;
}

bool isPressedEdge(int previous, int current)
{
    return previous == HIGH && current == LOW;
}

void reportLamp()
{
    Serial.print("foyer lamp=");
    Serial.println(lampLit ? "ON" : "OFF");
}

void setup()
{
    pinMode(SWITCH_PIN, INPUT_PULLUP);
    pinMode(LAMP_PIN, OUTPUT);
    driveLamp(false);
    Serial.begin(9600);
    previousRaw = digitalRead(SWITCH_PIN);
    lastStatusAt = millis();
    bootMs = millis();
}

void loop()
{
    int raw = digitalRead(SWITCH_PIN);
    unsigned long now = millis();

    if (raw == LOW)
    {
        if (isPressedEdge(previousRaw, raw))
        {
            lowSince = now;
        }
        if (pressArmed && (now - lowSince >= SETTLE_MS))
        {
            flipLamp();
            pressArmed = false;
        }
    }
    else
    {
        pressArmed = true;
    }
    previousRaw = raw;

    if (now - lastStatusAt >= STATUS_EVERY_MS)
    {
        lastStatusAt = now;
        reportLamp();
    }
}

// Packaging glue-dot solenoid driver.
// Trigger on D2 (pull-up), solenoid on D8, armed LED on D11.

const int TRIG_PIN = 2;
const int SOL_PIN = 8;
const int ARMED_PIN = 11;
const unsigned long PULSE_MS = 2500;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 500;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastTrig = HIGH;
unsigned long trigEdge = 0;
unsigned long lastHb = 0;
unsigned long dots = 0;

void solHigh()
{
    digitalWrite(SOL_PIN, HIGH);
}

void solLow()
{
    digitalWrite(SOL_PIN, LOW);
}

void setArmedLed(bool on)
{
    digitalWrite(ARMED_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("glue dots=");
    Serial.print(dots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(SOL_PIN, OUTPUT);
    pinMode(ARMED_PIN, OUTPUT);
    solLow();
    setArmedLed(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastTrig = stableTrig;
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (raw != lastTrig)
    {
        trigEdge = now;
        lastTrig = raw;
    }

    if ((now - trigEdge) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            dots++;
            solHigh();
            setArmedLed(false);
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        solLow();
        setArmedLed(true);
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

// Greenhouse ridge-vent controller.
// Soil-air LM35 on A2, exhaust fan relay on D9, UART status.

const int SENSOR_PIN = A2;
const int FAN_PIN = 9;
const float OPEN_C = 28.0f;
const float CLOSE_C = 24.0f;
const float FAULT_LOW_C = 5.0f;
const float FAULT_HIGH_C = 100.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 200;

bool fanOn = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
unsigned long sampleCount = 0;
float tempC = 0.0f;
float tempMin = 999.0f;
float tempMax = -999.0f;

bool pendingValid = false;
bool pendingState = false;
unsigned long pendingSince = 0;

float readTempC()
{
    int raw = analogRead(SENSOR_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void trackTemp(float c)
{
    if (c < tempMin)
    {
        tempMin = c;
    }
    if (c > tempMax)
    {
        tempMax = c;
    }
}

void setFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("gh: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        sampleCount++;
        trackTemp(tempC);

        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);
        bool desired;
        if (fault)
        {
            desired = true;
        }
        else if (tempC >= OPEN_C)
        {
            desired = true;
        }
        else if (tempC <= CLOSE_C)
        {
            desired = false;
        }
        else
        {
            desired = fanOn;
        }

        if (desired != fanOn)
        {
            if (!pendingValid || pendingState != desired)
            {
                pendingValid = true;
                pendingState = desired;
                pendingSince = now;
            }
            else if (now - pendingSince >= CONFIRM_MS)
            {
                setFan(desired);
                pendingValid = false;
            }
        }
        else
        {
            pendingValid = false;
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Shop hoist contactor with mushroom e-stop.
// E-stop on D3 (NC to ground via switch, pull-up), contactor on D5.
// Run request on D6 (pull-up).

const int ESTOP_PIN = 3;
const int CONTACTOR_PIN = 5;
const int RUN_PIN = 6;
const unsigned long SETTLE_MS = 30;
const unsigned long BEAT_MS = 1100;

int stableStop = HIGH;
int lastStop = HIGH;
unsigned long stopEdge = 0;
bool contactorOn = false;
unsigned long lastBeat = 0;
unsigned long tripCount = 0;

bool estopActive(int level)
{
    return level == LOW;
}

void setContactor(bool on)
{
    contactorOn = on;
    digitalWrite(CONTACTOR_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("hoist run=");
    Serial.print(contactorOn ? 1 : 0);
    Serial.print(" trips=");
    Serial.println(tripCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(RUN_PIN, INPUT_PULLUP);
    pinMode(CONTACTOR_PIN, OUTPUT);
    setContactor(false);
    Serial.begin(9600);
    stableStop = digitalRead(ESTOP_PIN);
    lastStop = stableStop;
    lastBeat = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(ESTOP_PIN);

    if (raw != lastStop)
    {
        stopEdge = now;
        lastStop = raw;
    }

    if ((now - stopEdge) >= SETTLE_MS && raw != stableStop)
    {
        if (estopActive(raw) && !estopActive(stableStop))
        {
            tripCount++;
        }
        stableStop = raw;
    }

    bool stopped = estopActive(stableStop);
    bool runReq = (digitalRead(RUN_PIN) == LOW);

    if (stopped)
    {
        setContactor(false);
    }
    else if (runReq)
    {
        setContactor(true);
    }
    else
    {
        setContactor(true);
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}

