// Process-skid flow monitor with low-flow alarm lamp.
// Flow transducer on A0 (2 mV per L/h), alarm lamp on D8.

const int FLOW_PIN = A0;
const int ALARM_PIN = 8;
const float LOW_FLOW_LPH = 100.0f;
const unsigned long LOG_MS = 500;
const unsigned long CONFIRM_MS = 20;

bool alarmLit = false;
bool pendingState = false;
bool havePending = false;
unsigned long pendingSince = 0;
unsigned long lastLog = 0;
unsigned long sampleCount = 0;
float flowLph = 0.0f;
float peakLph = 0.0f;

float readFlowLph()
{
    int raw = analogRead(FLOW_PIN);
    float millivolts = (float)raw * 5000.0f / 1023.0f;
    return millivolts / 2.0f;
}

void setAlarm(bool on)
{
    alarmLit = on;
    digitalWrite(ALARM_PIN, on ? HIGH : LOW);
}

bool flowLooksLow(float flow)
{
    return flow < LOW_FLOW_LPH;
}

void notePeak(float flow)
{
    if (flow > peakLph)
    {
        peakLph = flow;
    }
}

void emitLog()
{
    Serial.print("flow: ");
    Serial.println(flowLph, 1);
}

void updateAlarm(bool wantOn, unsigned long now)
{
    if (wantOn == alarmLit)
    {
        havePending = false;
        return;
    }
    if (!havePending || pendingState != wantOn)
    {
        havePending = true;
        pendingState = wantOn;
        pendingSince = now;
        return;
    }
    if (now - pendingSince >= CONFIRM_MS)
    {
        havePending = false;
        setAlarm(wantOn);
    }
}

void setup()
{
    pinMode(ALARM_PIN, OUTPUT);
    digitalWrite(ALARM_PIN, LOW);
    Serial.begin(9600);
    lastLog = millis();
    peakLph = 0.0f;
}

void loop()
{
    flowLph = readFlowLph();
    sampleCount++;
    notePeak(flowLph);

    unsigned long now = millis();
    updateAlarm(flowLooksLow(flowLph), now);

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        emitLog();
    }
}

// Linear rail carriage motor enable with end-stop.
// Limit switch on D2 (pull-up to GND when hit), motor enable on D13.
// Jog button on D4 (pull-up) requests motion when clear.

const int LIMIT_PIN = 2;
const int MOTOR_PIN = 13;
const int JOG_PIN = 4;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long STATUS_MS = 900;

int stableLimit = HIGH;
int lastLimit = HIGH;
unsigned long limitEdge = 0;
bool motorEnabled = false;
unsigned long lastStatus = 0;
unsigned long hitCount = 0;

bool limitActiveRaw()
{
    return digitalRead(LIMIT_PIN) == LOW;
}

void setMotor(bool enabled)
{
    motorEnabled = enabled;
    digitalWrite(MOTOR_PIN, enabled ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("rail motor=");
    Serial.print(motorEnabled ? 1 : 0);
    Serial.print(" hits=");
    Serial.println(hitCount);
}

void setup()
{
    pinMode(LIMIT_PIN, INPUT_PULLUP);
    pinMode(JOG_PIN, INPUT_PULLUP);
    pinMode(MOTOR_PIN, OUTPUT);
    setMotor(true);
    Serial.begin(9600);
    stableLimit = digitalRead(LIMIT_PIN);
    lastLimit = stableLimit;
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(LIMIT_PIN);

    if (raw != lastLimit)
    {
        limitEdge = now;
        lastLimit = raw;
    }

    if ((now - limitEdge) >= DEBOUNCE_MS && raw != stableLimit)
    {
        stableLimit = raw;
        if (limitActiveRaw())
        {
            hitCount++;
        }
    }

    bool hit = (stableLimit == LOW);
    bool jog = (digitalRead(JOG_PIN) == LOW);

    if (hit)
    {
        setMotor(false);
    }
    else if (jog)
    {
        setMotor(true);
    }
    else
    {
        setMotor(true);
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Shop bench run/stop: mushroom estop toggles the "machine armed" lamp.
// Estop contact on D6 (NC to ground via switch, pull-up), armed lamp on D9.

const uint8_t ESTOP_PIN = 6;
const uint8_t ARMED_PIN = 9;
const unsigned long BEAT_MS = 1200;
const unsigned long SETTLE_MS = 50;

bool armed = false;
uint8_t priorSample = HIGH;
bool pressPending = false;
unsigned long pressStart = 0;
unsigned long lastBeat = 0;
unsigned long pressCount = 0;
unsigned long bootMs = 0;

void writeArmed(bool level)
{
    armed = level;
    digitalWrite(ARMED_PIN, level ? HIGH : LOW);
}

void toggleArmed()
{
    writeArmed(!armed);
    pressCount++;
}

bool fallingEdge(uint8_t previous, uint8_t current)
{
    return previous == HIGH && current == LOW;
}

void heartbeat()
{
    Serial.print("shop armed=");
    Serial.print(armed ? 1 : 0);
    Serial.print(" presses=");
    Serial.println(pressCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(ARMED_PIN, OUTPUT);
    writeArmed(false);
    Serial.begin(9600);
    priorSample = digitalRead(ESTOP_PIN);
    lastBeat = millis();
    bootMs = millis();
}

void loop()
{
    uint8_t sample = digitalRead(ESTOP_PIN);
    unsigned long now = millis();

    if (fallingEdge(priorSample, sample))
    {
        pressPending = true;
        pressStart = now;
    }
    else if (sample == HIGH)
    {
        pressPending = false;
    }
    priorSample = sample;

    if (pressPending && (now - pressStart >= SETTLE_MS))
    {
        pressPending = false;
        toggleArmed();
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}

// CNC spindle tach display.
// Tach voltage on A5 (1 mV/rpm), warn lamp on D9, mute on D3.

const int TACH_PIN = A5;
const int WARN_PIN = 9;
const int MUTE_PIN = 3;
const float WARN_RPM = 2000.0f;
const unsigned long PERIOD_MS = 1000;
const unsigned long SAMPLE_MS = 50;

unsigned long lastPrint = 0;
unsigned long lastSample = 0;
float rpm = 0.0f;
float rpmMin = 99999.0f;
float rpmMax = 0.0f;
bool warnLit = false;

float readRpm()
{
    int raw = analogRead(TACH_PIN);
    return raw * (5000.0f / 1023.0f);
}

void trackExtremes(float v)
{
    if (v < rpmMin)
    {
        rpmMin = v;
    }
    if (v > rpmMax)
    {
        rpmMax = v;
    }
}

void updateWarn(float v)
{
    bool muted = (digitalRead(MUTE_PIN) == LOW);
    warnLit = (!muted) && (v >= WARN_RPM);
    digitalWrite(WARN_PIN, warnLit ? HIGH : LOW);
}

void printRpm(float v)
{
    Serial.print("RPM:");
    Serial.println(v, 0);
}

void setup()
{
    pinMode(WARN_PIN, OUTPUT);
    pinMode(MUTE_PIN, INPUT_PULLUP);
    digitalWrite(WARN_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
    lastSample = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        rpm = readRpm();
        trackExtremes(rpm);
        updateWarn(rpm);
    }

    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printRpm(rpm);
        Serial.print("spindle min=");
        Serial.print(rpmMin, 0);
        Serial.print(" max=");
        Serial.println(rpmMax, 0);
    }
}

// Safe-deposit vault lock latch.
// Request button on D2, door-closed sense on D3 (both pull-up), lock solenoid on D9.

const int REQ_PIN = 2;
const int DOOR_PIN = 3;
const int LOCK_PIN = 9;
const unsigned long DEBOUNCE_MS = 35;
const unsigned long STATUS_MS = 1000;

bool locked = false;
int stableReq = HIGH;
int lastReq = HIGH;
unsigned long reqEdge = 0;
unsigned long lastStatus = 0;
unsigned long engageCount = 0;

void setLock(bool on)
{
    locked = on;
    digitalWrite(LOCK_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("vault lock=");
    Serial.print(locked ? 1 : 0);
    Serial.print(" engages=");
    Serial.println(engageCount);
}

bool doorClosed()
{
    return digitalRead(DOOR_PIN) == LOW;
}

void setup()
{
    pinMode(REQ_PIN, INPUT_PULLUP);
    pinMode(DOOR_PIN, INPUT_PULLUP);
    pinMode(LOCK_PIN, OUTPUT);
    setLock(false);
    Serial.begin(9600);
    stableReq = digitalRead(REQ_PIN);
    lastReq = stableReq;
    reqEdge = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(REQ_PIN);

    if (raw != lastReq)
    {
        reqEdge = now;
        lastReq = raw;
    }

    if ((now - reqEdge) >= DEBOUNCE_MS && raw != stableReq)
    {
        stableReq = raw;
    }

    if (stableReq == LOW && doorClosed() && !locked)
    {
        setLock(true);
        engageCount++;
    }

    if (locked && !doorClosed())
    {
        setLock(false);
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Walk-in cooler compressor controller.
// Cabinet probe on A3 (10 mV/°C), compressor on D7, service switch on D4.

const int TEMP_PIN = A3;
const int COMP_PIN = 7;
const int SERVICE_PIN = 4;
const float COOL_ON_C = 8.0f;
const float COOL_OFF_C = 4.0f;
const float FAULT_LOW_C = 0.0f;
const float FAULT_HIGH_C = 60.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 100;

bool cooling = false;
bool onPending = false;
bool offPending = false;
unsigned long onSince = 0;
unsigned long offSince = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setCompressor(bool on)
{
    cooling = on;
    digitalWrite(COMP_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("cooler: ");
    Serial.print(tempC, 1);
    Serial.print(" C comp=");
    Serial.println(cooling ? "ON" : "OFF");
}

void setup()
{
    pinMode(COMP_PIN, OUTPUT);
    pinMode(SERVICE_PIN, INPUT_PULLUP);
    setCompressor(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        bool service = (digitalRead(SERVICE_PIN) == LOW);
        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

        if (service || fault)
        {
            onPending = false;
            offPending = false;
            setCompressor(false);
        }
        else
        {
            if (tempC >= COOL_ON_C)
            {
                if (!onPending)
                {
                    onPending = true;
                    onSince = now;
                }
                offPending = false;
            }
            else if (tempC <= COOL_OFF_C)
            {
                if (!offPending)
                {
                    offPending = true;
                    offSince = now;
                }
                onPending = false;
            }
            else
            {
                onPending = false;
                offPending = false;
            }

            if (onPending && (now - onSince >= CONFIRM_MS))
            {
                setCompressor(true);
                onPending = false;
            }
            else if (offPending && (now - offSince >= CONFIRM_MS))
            {
                setCompressor(false);
                offPending = false;
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Patio weather node: TMP36 logger with hold-to-freeze button.
// TMP36 on A0 (10 mV/°C + 500 mV), freeze button on D5, range lamp on D7.

const int TEMP_PIN = A0;
const int FREEZE_PIN = 5;
const int RANGE_PIN = 7;
const float MV_PER_C = 10.0f;
const float OFFSET_MV = 500.0f;
const float LOW_C = -10.0f;
const float HIGH_C = 50.0f;
const unsigned long PERIOD_MS = 1000;

unsigned long lastPrint = 0;
float tempC = 0.0f;
float frozenC = 0.0f;
bool freezeHeld = false;
unsigned long samples = 0;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float volts = raw * (5.0f / 1023.0f);
    return (volts - (OFFSET_MV / 1000.0f)) * 100.0f;
}

void updateRangeLamp(float c)
{
    bool ok = (c >= LOW_C) && (c <= HIGH_C);
    digitalWrite(RANGE_PIN, ok ? LOW : HIGH);
}

void printTemp(float c)
{
    Serial.print("Temp: ");
    Serial.println(c, 1);
}

void setup()
{
    pinMode(FREEZE_PIN, INPUT_PULLUP);
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
}

void loop()
{
    tempC = readTempC();
    samples++;
    freezeHeld = (digitalRead(FREEZE_PIN) == LOW);
    if (freezeHeld)
    {
        frozenC = tempC;
    }

    float report = freezeHeld ? frozenC : tempC;
    updateRangeLamp(report);

    unsigned long now = millis();
    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printTemp(report);
        Serial.print("weather n=");
        Serial.println(samples);
    }
}

// Compressed-air manifold pressure logger for the workshop.
// Transducer on A2: 10 mV/kPa with 500 mV zero offset. Gauge lamp on D12.

const int PRESSURE_PIN = A2;
const int GAUGE_PIN = 12;
const float WARN_KPA = 90.0f;
const float MV_PER_KPA = 10.0f;
const float ZERO_MV = 500.0f;
const unsigned long SAMPLE_MS = 1000;
const unsigned long GAUGE_CONFIRM_MS = 100;

unsigned long lastSample = 0;
unsigned long readingCount = 0;
float lastKpa = 0.0f;
float minKpa = 9999.0f;
float maxKpa = 0.0f;
bool gaugeLit = false;
bool gaugePending = false;
bool gaugePendingState = false;
unsigned long gaugePendingSince = 0;

float readMillivolts()
{
    int raw = analogRead(PRESSURE_PIN);
    return raw * (5000.0f / 1023.0f);
}

float millivoltsToKpa(float mv)
{
    return (mv - ZERO_MV) / MV_PER_KPA;
}

void trackExtremes(float kpa)
{
    if (kpa < minKpa)
    {
        minKpa = kpa;
    }
    if (kpa > maxKpa)
    {
        maxKpa = kpa;
    }
}

void updateGauge(float kpa)
{
    bool want = (kpa >= WARN_KPA);
    unsigned long now = millis();

    if (want == gaugeLit)
    {
        gaugePending = false;
        return;
    }

    if (!gaugePending || gaugePendingState != want)
    {
        gaugePending = true;
        gaugePendingState = want;
        gaugePendingSince = now;
        return;
    }

    if (now - gaugePendingSince >= GAUGE_CONFIRM_MS)
    {
        gaugeLit = want;
        digitalWrite(GAUGE_PIN, gaugeLit ? HIGH : LOW);
        gaugePending = false;
    }
}

void printReading()
{
    Serial.print("kPa: ");
    Serial.println(lastKpa, 1);
}

void setup()
{
    pinMode(GAUGE_PIN, OUTPUT);
    digitalWrite(GAUGE_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
}

void loop()
{
    float mv = readMillivolts();
    float kpa = millivoltsToKpa(mv);
    updateGauge(kpa);

    unsigned long now = millis();
    if (now - lastSample < SAMPLE_MS)
    {
        return;
    }
    lastSample = now;

    lastKpa = kpa;
    readingCount++;
    trackExtremes(lastKpa);
    printReading();
}

// Yard path lamp dusk relay.
// Light sensor on A0 (mV as lux-ish units), relay on D8, manual on D3.

const int LIGHT_PIN = A0;
const int RELAY_PIN = 8;
const int MANUAL_PIN = 3;
const float ON_UNITS = 400.0f;
const float OFF_UNITS = 600.0f;
const unsigned long SAMPLE_MS = 40;
const unsigned long STATUS_MS = 1000;

bool relayOn = false;
unsigned long lastSample = 0;
unsigned long lastStatus = 0;
float lightU = 0.0f;

float readLightUnits()
{
    int raw = analogRead(LIGHT_PIN);
    return raw * (5000.0f / 1024.0f);
}

void setRelay(bool on)
{
    relayOn = on;
    digitalWrite(RELAY_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("yard u=");
    Serial.print(lightU, 0);
    Serial.print(" relay=");
    Serial.println(relayOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(RELAY_PIN, OUTPUT);
    pinMode(MANUAL_PIN, INPUT_PULLUP);
    setRelay(false);
    Serial.begin(9600);
    lastSample = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        lightU = readLightUnits();
        bool manual = (digitalRead(MANUAL_PIN) == LOW);

        if (manual)
        {
            setRelay(true);
        }
        else if (lightU < ON_UNITS)
        {
            setRelay(true);
        }
        else if (lightU > OFF_UNITS)
        {
            setRelay(false);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}
